import{_ as e,o as s,c as r,ai as n}from"./chunks/framework.ampVZV4B.js";const g=JSON.parse('{"title":"10. 实战场景","description":"","frontmatter":{},"headers":[],"relativePath":"redis/10-practice.md","filePath":"redis/10-practice.md"}'),i={name:"redis/10-practice.md"};function l(t,a,o,h,c,d){return s(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="_10-实战场景" tabindex="-1">10. 实战场景 <a class="header-anchor" href="#_10-实战场景" aria-label="Permalink to “10. 实战场景”">​</a></h1><p>把前面能力落到可口述的业务故事。每条：<strong>场景 → Redis 怎么用 → 核心优化 → 边界</strong>。</p><p>更细的缓存架构推演见：<a href="./cache-scenario.html">场景实战：缓存设计</a>。<br> 秒杀系统设计还可对照：<a href="/my-vitepress-site/scenarios/seckill.html">秒杀系统</a>。</p><hr><h2 id="登录-会话" tabindex="-1">登录 / 会话 <a class="header-anchor" href="#登录-会话" aria-label="Permalink to “登录 / 会话”">​</a></h2><ul><li><strong>用法：</strong> String / Hash 存 token 或 session；<code>EXPIRE</code> 控制登录态</li><li><strong>优化：</strong> Key 带用户维度；续期滑动过期；敏感信息不落明文</li><li><strong>边界：</strong> 强制下线、多端互踢要有版本号或 token 黑名单</li></ul><hr><h2 id="秒杀" tabindex="-1">秒杀 <a class="header-anchor" href="#秒杀" aria-label="Permalink to “秒杀”">​</a></h2><ul><li><strong>用法：</strong> 库存预扣在 Redis（Lua 判断 + DECR）；成功再异步下单</li><li><strong>优化：</strong> 分桶库存打散热 Key；接口限流；缓存与 DB 对账</li><li><strong>边界：</strong> 支付与订单以 DB 为准；Redis 防超卖，不是账务系统</li></ul><p>详见：<a href="./07-concurrency.html">并发：库存</a> · <a href="./distributed-lock.html">分布式锁</a></p><hr><h2 id="点赞-计数" tabindex="-1">点赞 / 计数 <a class="header-anchor" href="#点赞-计数" aria-label="Permalink to “点赞 / 计数”">​</a></h2><ul><li><strong>用法：</strong> <code>INCR</code> 计总数；Set 记「谁点过」防重复</li><li><strong>优化：</strong> 计数与明细分离；高峰异步落库</li><li><strong>边界：</strong> 计数可最终一致；审计明细需要持久化</li></ul><hr><h2 id="排行榜" tabindex="-1">排行榜 <a class="header-anchor" href="#排行榜" aria-label="Permalink to “排行榜”">​</a></h2><ul><li><strong>用法：</strong> ZSet，score 为热度/分数；<code>ZREVRANGE</code> 取 TopN</li><li><strong>优化：</strong> 定时快照；超大榜分页与裁剪；防刷分</li><li><strong>边界：</strong> 实时榜与日榜/周榜可用不同 Key</li></ul><hr><h2 id="分布式锁" tabindex="-1">分布式锁 <a class="header-anchor" href="#分布式锁" aria-label="Permalink to “分布式锁”">​</a></h2><ul><li><strong>用法：</strong> 互斥更新、防重复提交、定时任务多实例</li><li><strong>优化：</strong> Redisson + 看门狗；解锁校验持有者；业务可重入要明确</li><li><strong>边界：</strong> 锁粒度尽量细；锁内禁止超长远程调用</li></ul><p>详见：<a href="./distributed-lock.html">分布式锁</a></p><hr><h2 id="接口限流" tabindex="-1">接口限流 <a class="header-anchor" href="#接口限流" aria-label="Permalink to “接口限流”">​</a></h2><ul><li><strong>用法：</strong> Redis 计数器 / 滑动窗口；网关 + 业务双层</li><li><strong>优化：</strong> Key 设计含接口与主体；过期防泄漏；返回明确错误码</li><li><strong>边界：</strong> 全局限流与用户级限流分开</li></ul><p>详见：<a href="./07-concurrency.html">并发：限流</a></p><hr><h2 id="缓存架构" tabindex="-1">缓存架构 <a class="header-anchor" href="#缓存架构" aria-label="Permalink to “缓存架构”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>客户端</span></span>
<span class="line"><span>  →（可选）Nginx / 本地短缓存</span></span>
<span class="line"><span>  → 应用 Caffeine（热点）</span></span>
<span class="line"><span>  → Redis</span></span>
<span class="line"><span>  → MySQL</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li><strong>优化：</strong> Cache Aside（先更新 DB 再删缓存）；过期随机；空值防穿透；热点本地挡</li><li><strong>一致性：</strong> 普通业务删缓存即可；强一致需求上 Binlog 监听或短时双删</li></ul><p>详见：<a href="./cache-issues.html">缓存问题</a> · <a href="./cache-scenario.html">缓存设计实战</a></p><hr><h2 id="口述总模板" tabindex="-1">口述总模板 <a class="header-anchor" href="#口述总模板" aria-label="Permalink to “口述总模板”">​</a></h2><blockquote><p>我们用 Redis 做缓存和分布式协调。读路径多级缓存防击穿雪崩；写路径更新 DB 后删缓存。库存和限流用 Lua 保证原子。锁用 Redisson 续期。大 Key / 热 Key 会拆分或加本地缓存。持久化与主从按环境配置，集群在需要水平扩展时再上。</p></blockquote><p>自测：每个场景能不看稿讲 30～60 秒，并回答一个追问（一致性 / 超卖 / 锁超时）。</p>`,33)])])}const b=e(i,[["render",l]]);export{g as __pageData,b as default};
